<?php require __DIR__.'/config.php'; $message=''; if($_SERVER['REQUEST_METHOD']==='POST'){ $name=trim($_POST['name']??'');$email=filter_var($_POST['email']??'',FILTER_VALIDATE_EMAIL);$password=$_POST['password']??''; if(!$name||!$email||strlen($password)<8){$message='Enter valid details; password must be at least 8 characters.';}else{$hash=password_hash($password,PASSWORD_DEFAULT);try{$q=$pdo->prepare('INSERT INTO users(name,email,password_hash) VALUES(?,?,?)');$q->execute([$name,$email,$hash]);$message='Registration successful.';}catch(PDOException $e){$message='Email may already be registered.';}}} ?>
<p><?= htmlspecialchars($message) ?></p><form method="post"><input name="name" required placeholder="Name"><input name="email" type="email" required placeholder="Email"><input name="password" type="password" required minlength="8" placeholder="Password"><button>Register</button></form>